 currentPage='home';
 let bn=lang==='bn', role=isMgr()?(bn?'ম্যানেজার · টিম কমান্ড':'Manager · Team Command'):(bn?'সেলস রিপ্রেজেন্টেটিভ':'Sales Representative');
