async function ffhDataUrlUpload(dataUrl,bucket,path){
 if(!/^data:/i.test(String(dataUrl||'')))return dataUrl;
 let m=String(dataUrl).match(/^data:([^;]+);base64,(.+)$/);if(!m)return dataUrl;
 let mime=m[1],bin=atob(m[2]),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
 let ext=(mime.split('/')[1]||'jpg').replace('jpeg','jpg').replace(/[^a-z0-9]/gi,'')||'jpg';let full=path+'.'+ext;
 let {error}=await FFH_SUPABASE.storage.from(bucket).upload(full,bytes,{contentType:mime,upsert:true});if(error)throw error;
 if(bucket==='ffh-public'){let {data}=FFH_SUPABASE.storage.from(bucket).getPublicUrl(full);return data.publicUrl}
 return full;
}
async function ffhCloudifyLocalData(source,onProgress){
 let out=JSON.parse(JSON.stringify(source||{})),jobs=[];
 const add=(obj,key,bucket,path)=>{if(obj&&/^data:/i.test(String(obj[key]||'')))jobs.push({obj,key,bucket,path})};
 let stamp='migration/'+(user?.id||'manager')+'/'+Date.now();
 (out.users||[]).forEach((x,i)=>add(x,'photo','ffh-public',stamp+'/profiles/'+(x.id||i)));
 (out.catalogue||[]).forEach((x,i)=>add(x,'image','ffh-public',stamp+'/catalogue/product-'+i));
 Object.entries(out.catalogueCategories||{}).forEach(([k,x],i)=>{if(typeof x==='object')add(x,'cover','ffh-public',stamp+'/catalogue/category-'+i)});
 (out.cpoCampaigns||[]).forEach((x,i)=>add(x,'image','ffh-public',stamp+'/campaigns/campaign-'+i));
 (out.incentives||[]).forEach((x,i)=>add(x,'image','ffh-public',stamp+'/incentives/incentive-'+i));
 (out.cpo||[]).forEach((x,i)=>{add(x,'photo','ffh-private','proofs/'+(x.sr||user?.id||'unknown')+'/migration/proof-'+i);add(x,'image','ffh-private','proofs/'+(x.sr||user?.id||'unknown')+'/migration/proof-'+i)});
 for(let i=0;i<jobs.length;i++){let j=jobs[i];onProgress?.('Uploading images '+(i+1)+' / '+jobs.length+'…');j.obj[j.key]=await ffhDataUrlUpload(j.obj[j.key],j.bucket,j.path)}
 return out;
}
async function ffhInsertIfEmpty(table,rows,onProgress){
 rows=(rows||[]).filter(Boolean);if(!rows.length)return{table,status:'EMPTY',local:0,cloud:0};
 let {count,error:ce}=await FFH_SUPABASE.from(table).select('*',{count:'exact',head:true});if(ce)throw ce;
 if((count||0)>0)return{table,status:'SKIPPED_EXISTING',local:rows.length,cloud:count||0};
 onProgress?.('Writing '+table+'…');let {error}=await FFH_SUPABASE.from(table).insert(rows);if(error)throw error;
 let {count:after,error:ae}=await FFH_SUPABASE.from(table).select('*',{count:'exact',head:true});if(ae)throw ae;
 return{table,status:after===rows.length?'PASS':'CHECK',local:rows.length,cloud:after||0};
}
function ffhMigrationRows(d){
 let users=d.users||[],out=[];users.forEach(u=>(d.customOutlets?.[u.id]||[]).forEach(o=>out.push({sr_id:u.id,outlet_code:o.code||'',outlet_name:o.name||'',category:o.category||'Other',total_sku:+o.totalSku||0,active:true,source:'local-migration'})));
 let cats=Object.entries(d.catalogueCategories||{}).map(([name,v],i)=>({name,cover_url:typeof v==='object'?(v.cover||v.image||''):'',sort_order:i,active:true}));
 let prods=(d.catalogue||[]).map(x=>({name:x.name,category:x.category||'Uncategorized',carton_qty:+x.cartonQty||0,piece_price:+x.piecePrice||0,carton_price:+x.cartonPrice||0,image_url:x.image||'',active:true}));
 let sales=(d.sales||[]).map(x=>({sr_id:x.sr,sale_date:x.date||today(),outlet_code:x.outletCode||'',outlet_name:x.outletName||'',category:x.category||'Other',sku:x.sku||'',qty:+x.qty||0,price:+x.price||0,order_amount:+x.orderAmount||0,delivered_amount:+x.deliveredAmount||0,status:x.status||'Pending Delivery',remarks:x.remarks||'',delivered_at:x.deliveredAt||null}));
 let tasks=(d.tasks||[]).map(x=>({title:x.title||'Task',description:x.description||x.note||'',assigned_to:x.to||'ALL',given_by:x.by||x.from||'Manager',given_by_id:x.from||'M21954',due_date:x.due||null,priority:x.priority||'MEDIUM',status:x.status||'Open',created_date:x.date||today(),done_at:x.doneAt||null}));
 let routes=[];Object.entries(d.routes||{}).forEach(([k,v])=>{if(v&&typeof v==='object'&&!Array.isArray(v))Object.entries(v).forEach(([sid,payload])=>routes.push({sr_id:sid,route_date:k,payload}));else routes.push({sr_id:user?.id||'M21954',route_date:k,payload:v})});
 let campaigns=(d.cpoCampaigns||[]).map(x=>({title:x.title||'Campaign',campaign_type:x.type||'CPO',execution_mode:x.executionMode||'proof',assigned_to:x.sr||'ALL',outlet_category:x.category||'ALL',product:x.product||'',poster_url:x.image||'',start_date:x.startDate||x.date||today(),end_date:x.endDate||x.startDate||x.date||today(),active:x.active!==false}));
 let incentives=(d.incentives||[]).map(x=>({name:x.name||'Incentive',assigned_to:x.sr||'ALL',poster_url:x.image||'',groups:x.groups||[],start_date:x.startDate||x.date||today(),end_date:x.endDate||x.startDate||x.date||today(),active:x.active!==false}));
 let proposals=(d.proposals||[]).filter(x=>!/^data:/i.test(String(x.file||''))).map(x=>({name:x.name||'Proposal',category:x.category||'',logo_url:x.logo||'',file_url:x.file||'',filename:x.filename||'',created_date:x.date||today()}));
 let adjustments=(d.adjustments||[]).map(x=>({sr_id:x.sr,month:x.month||month(),kind:x.kind||'',amount:+x.amount||0,reason:x.reason||'',given_by:x.by||'',adjustment_date:x.date||today()}));
 let kb=(d.kb?.qaPairs||[]).map(x=>({question:x.question,answer:x.answer,active:true,created_by:user?.id||'M21954'}));
 return{ffh_outlets:out,ffh_catalogue_categories:cats,ffh_catalogue_products:prods,ffh_sales:sales,ffh_tasks:tasks,ffh_routes:routes,ffh_campaigns:campaigns,ffh_incentives:incentives,ffh_proposals:proposals,ffh_adjustments:adjustments,ffh_ai_knowledge:kb};
}
async function ffhRunMigration(statusEl,btn){
 if(!isMgr())return;let set=t=>{if(statusEl)statusEl.textContent=t};btn.disabled=true;
 try{
  set('Step 1/4 — Reading existing local data…');let cloud=await ffhCloudifyLocalData(db,set);
  set('Step 2/4 — Saving full safety snapshot…');let payload={...cloud,_migration:{source_key:K,staff_id:user.id,created_at:new Date().toISOString()}};
  let {data:snap,error:se}=await FFH_SUPABASE.from('ffh_migration_snapshots').insert({device_label:navigator.userAgent.slice(0,120),staff_id:user.id,app_build:'FFH-SUPABASE-MIGRATION-V1',payload,verified:false}).select('id').single();if(se)throw se;
  set('Step 3/4 — Copying records to cloud tables…');let rows=ffhMigrationRows(cloud),results=[];for(let [table,r] of Object.entries(rows))results.push(await ffhInsertIfEmpty(table,r,set));
  let bad=results.filter(x=>x.status==='CHECK');if(bad.length)throw new Error('Verification mismatch: '+bad.map(x=>x.table).join(', '));
  set('Step 4/4 — Verifying safety snapshot…');let {data:check,error:ve}=await FFH_SUPABASE.from('ffh_migration_snapshots').select('id,staff_id,verified').eq('id',snap.id).single();if(ve||!check)throw ve||new Error('Snapshot verification failed');
  let {error:ue}=await FFH_SUPABASE.from('ffh_migration_snapshots').update({verified:true}).eq('id',snap.id);if(ue)throw ue;
  localStorage.setItem('ffh_cloud_migration_verified',JSON.stringify({snapshot_id:snap.id,at:new Date().toISOString(),results}));
  set('VERIFIED ✅ Existing local data is backed up in Supabase. Local data has NOT been deleted.');alert('Cloud migration VERIFIED ✅\n\nYour local data is still preserved. Do not clear it yet.');
 }catch(e){console.error(e);set('FAILED ❌ '+(e?.message||e));alert('Migration stopped safely. Local data was NOT deleted.\n\n'+(e?.message||e))}finally{btn.disabled=false}
}
function ffhMigrationPage(){
 if(!isMgr())return home();let local=JSON.parse(localStorage.getItem(K)||'{}');let prev=localStorage.getItem('ffh_migration_verified')==='1';shell(back('Sync Existing Data to Cloud')+`<div class="card"><div class="cardTitle">One-Time Safe Migration</div><div class="notice">এই phone/browser-এর বর্তমান data-ই source of truth। Verification PASS না হওয়া পর্যন্ত local data delete বা cloud-only mode চালু হবে না।</div><div class="row"><span>Local sales</span><b>${(local.sales||[]).length}</b></div><div class="row"><span>Catalogue products</span><b>${(local.catalogue||[]).length}</b></div><div class="row"><span>CPO / Promotion records</span><b>${(local.cpoCampaigns||[]).length}</b></div><div class="row"><span>Tasks</span><b>${(local.tasks||[]).length}</b></div><div class="row"><span>Previous verified migration</span><b>${prev?'YES':'NO'}</b></div><button class="primary" id="startCloudMigration">SYNC EXISTING DATA TO CLOUD</button><div id="migrationStatus" class="notice">Ready. Local data will not be cleared.</div></div>`);bindBack();q('#startCloudMigration').onclick=async()=>{let b=q('#startCloudMigration'),st=q('#migrationStatus'),stage='Starting';b.disabled=true;const set=x=>{stage=x;st.textContent=x};try{set('Step 1/5 — Creating authenticated safety snapshot…');let payload=JSON.parse(localStorage.getItem(K)||'{}');let {data:snap,error:se}=await FFH_SUPABASE.from('ffh_migration_snapshots').insert({device_label:navigator.userAgent.slice(0,120),staff_id:user.id,app_build:'FFH-MIGRATION-V3',payload,verified:false}).select('id').single();if(se)throw se;set('Step 2/5 — Uploading local images safely…');let cloud=await ffhCloudifyLocalData(payload,set);set('Step 3/5 — Copying supported records…');let rows=ffhMigrationRows(cloud),results=[];for(let [table,data] of Object.entries(rows))results.push(await ffhInsertIfEmpty(table,data,set));set('Step 4/5 — Verifying snapshot…');let {data:check,error:ve}=await FFH_SUPABASE.from('ffh_migration_snapshots').select('id,staff_id').eq('id',snap.id).single();if(ve||!check)throw ve||new Error('Snapshot verification failed');let {error:ue}=await FFH_SUPABASE.from('ffh_migration_snapshots').update({verified:true}).eq('id',snap.id);if(ue)throw ue;localStorage.setItem('ffh_migration_verified','1');set('VERIFIED ✅ Local data preserved. Cloud safety snapshot completed.');}catch(e){console.error('Migration failed at',stage,e);st.textContent='FAILED ❌ '+stage+' — '+(e?.message||e);st.classList.add('red')}finally{b.disabled=false}}
}

