function aiWelcomeText(){let n=displayFirstName(),g=greetingNow();if(lang==='bn'){let bg=g==='Good Morning'?'শুভ সকাল':g==='Good Afternoon'?'শুভ অপরাহ্ন':g==='Good Evening'?'শুভ সন্ধ্যা':'শুভ রাত্রি';return `${bg}, ${n} স্যার!`; }return `${g}, ${n} Sir!`}
function aiShortIntro(){return lang==='bn'?'আমি আপনার Sales Assistant — AYON AI':'I am your Sales Assistant — AYON AI'}
function chooseAIVoice(text=''){let vs=window.speechSynthesis?.getVoices?.()||[],isBn=/[\u0980-\u09FF]/.test(text);if(!vs.length)return null;let langList=isBn?vs.filter(v=>/^bn(?:-|$)/i.test(v.lang||'')):vs.filter(v=>/^en-(?:GB|US|IN|AU)/i.test(v.lang||''));let male=/male|guy|david|mark|daniel|ryan|george|ravi|prabhat|hemant|madhur/i,natural=/google|microsoft|natural|online|neural|bangla|bengali/i;return langList.find(v=>male.test((v.name||'')+' '+(v.voiceURI||'')))||langList.find(v=>natural.test((v.name||'')+' '+(v.voiceURI||'')))||langList[0]||vs.find(v=>male.test(v.name||''))||vs[0]}
function aiSpeechClean(t){let x=String(t||'').replace(/[👋😄🎯⚡✦♢💪]/g,'').replace(/AYON/gi,'অয়ন').replace(/Mehedi\s+Alim\s+Ayon/gi,'মেহেদী আলিম অয়ন').replace(/RM\s*/g,/[\u0980-\u09FF]/.test(t)?'রিঙ্গিত ':'RM ');return x.replace(/CPO\s*\/\s*(?:DPO|Promotion)/gi,'সি পি ও, প্রোমোশন').replace(/\bPO\b/gi,'পি ও')}
function aiSpeak(t){try{if(!('speechSynthesis' in window))return;speechSynthesis.cancel();let clean=aiSpeechClean(t),isBn=/[\u0980-\u09FF]/.test(clean),u=new SpeechSynthesisUtterance(clean);u.lang=isBn?'bn-BD':'en-GB';u.rate=isBn?.70:.90;u.pitch=isBn?.88:.92;u.volume=1;let v=chooseAIVoice(clean);if(v){u.voice=v;if(!isBn)u.lang=v.lang||u.lang}window._ffhVoice=u;speechSynthesis.speak(u)}catch(_){}}
function stopAIVoice(){try{speechSynthesis.cancel()}catch(_){}}
function closeAIPopup(){stopAIVoice();q('#aiPopup')?.remove()}
function aiQuickQuestions(){return lang==='bn'?[['▥','আমার সেলস কেমন?','আজ, এই সপ্তাহ বা এই মাস'],['◎','আমার টার্গেট প্রোগ্রেস?','টার্গেট বনাম অ্যাচিভমেন্ট'],['▣','কোন আউটলেটে ফোকাস দেব?','পারফরম্যান্স অনুযায়ী সাজেশন'],['▤','CPO / Promotion স্ট্যাটাস','অর্ডার, ডেলিভারি ও এক্সিকিউশন'],['⌖','আজকের রুট প্ল্যান দেখাও','ভিজিট এবং কভারেজ'],['$','আমার ইনকাম আপডেট','বেতন, ইনসেনটিভ ও বোনাস']]:[['▥','How are my sales?','Today, this week or this month'],['◎','My target progress?','Target versus achievement'],['▣','Which outlets need focus?','Suggestions from performance'],['▤','CPO / Promotion status','Order, delivery and execution'],['⌖','Show today’s route plan','Visits and coverage'],['$','My income update','Salary, incentive and bonus']]}
function toggleAIPopup(){if(q('#aiPopup'))closeAIPopup();else openAIPopup()}
function openAIPopup(){q('#aiPopup')?.remove();q('#aiHello')?.remove();let welcome=aiWelcomeText(),qs=aiQuickQuestions();let o=document.createElement('div');o.id='aiPopup';o.className='aiPopupOverlay aiFloatingOverlay';o.innerHTML=`<section class="aiPopupPanel"><button class="aiVoiceStop" id="aiVoiceStop" title="${lang==='bn'?'ভয়েস বন্ধ':'Mute voice'}">🔇</button><div class="aiPopupLeft"><div class="growTogether">Let’s<br>Grow<br>Together!</div><div class="aiSideBrand"><img src="fieldforce-logo.jpg" alt="FieldForce Hub logo"><b>FieldForce Hub</b><small>Sales | Delivery | Performance | Growth</small></div><div class="aiIdentityTop"><strong>Mehedi Alim Ayon</strong><small>Key Account Manager</small></div><div class="aiPortraitFade"><img src="ayon-full-transparent.png" onerror="this.src='330441.png'" class="aiFullPortrait"></div><div class="aiMotto">Smart People<br>Stronger Team<br><b>Bigger Tomorrow</b></div></div><div class="aiPopupMain"><div class="aiPopupTitle"><span>✦</span><div><h2>AYON <b>AI</b></h2><p>${lang==='bn'?'আপনার Sales Intelligence Assistant':'Your Sales Intelligence Assistant'}</p></div></div><div class="aiStatus"><i></i> Online <span>|</span> Data-aware <span>|</span> Permission-aware <span>|</span> Voice enabled</div><div class="aiWelcome compactWelcome"><b>✦</b><p><strong>${esc(welcome)}</strong><small>${esc(aiShortIntro())}</small></p></div><h3>⚡ ${lang==='bn'?'আপনি যা জানতে পারেন:':'You can ask:'}</h3><div class="aiQuickGrid">${qs.map(x=>`<button class="aiQuick" data-q="${esc(x[1])}"><i>${x[0]}</i><span><b>${esc(x[1])}</b><small>${esc(x[2])}</small></span><em>›</em></button>`).join('')}</div><div class="aiPopupChat" id="aiPopupChat"></div><div class="aiPopupComposer"><button id="aiPopupMic">🎙</button><input id="aiPopupAsk" placeholder="${lang==='bn'?'AYON AI-কে জিজ্ঞেস করুন...':'Ask AYON AI...'}"><button id="aiPopupSend">➤</button></div><small class="aiDisclaimer">♢ AI may not be 100% accurate. Please verify critical information.</small></div></section>`;document.body.appendChild(o);q('#aiVoiceStop').onclick=stopAIVoice;qa('.aiQuick',o).forEach(b=>b.onclick=()=>{q('#aiPopupAsk').value=b.dataset.q;askAIPopup()});q('#aiPopupSend').onclick=askAIPopup;q('#aiPopupAsk').onkeydown=e=>e.key==='Enter'&&askAIPopup();setupPopupMic();}
function setupPopupMic(){let B=q('#aiPopupMic');if(!B)return;let SR=window.SpeechRecognition||window.webkitSpeechRecognition;const note=msg=>{let c=q('#aiPopupChat');if(c){c.innerHTML+=`<div class="bubble bot voiceNote">${esc(msg)}</div>`;c.scrollTop=c.scrollHeight}};if(!SR){B.onclick=()=>note('স্যার, এই ব্রাউজারে voice-to-text পাওয়া যাচ্ছে না। Chrome-এ microphone permission Allow করে আবার চেষ্টা করুন।');return}let r=null,busy=false;const build=()=>{r=new SR();r.lang=lang==='bn'?'bn-BD':'en-US';r.interimResults=false;r.continuous=false;r.maxAlternatives=3;r.onstart=()=>{busy=true;B.classList.add('listening');B.textContent='●'};r.onresult=e=>{let t='';for(let i=e.resultIndex;i<e.results.length;i++){if(e.results[i].isFinal)t+=(t?' ':'')+e.results[i][0].transcript}t=t.trim();let I=q('#aiPopupAsk');if(I&&t){I.value=t;setTimeout(()=>askAIPopup(),80)}};r.onerror=e=>{busy=false;B.classList.remove('listening');B.textContent='🎙';if(e.error==='not-allowed'||e.error==='service-not-allowed')note('স্যার, Microphone permission Allow করুন, তারপর আবার mic চাপুন।');else if(e.error==='no-speech')note('স্যার, কথাটা শুনতে পাইনি। Mic-এর কাছে একটু স্পষ্ট করে আবার বলুন।');else if(e.error==='network')note('স্যার, ফোনের speech service network পাচ্ছে না। Internet on রেখে আবার mic চাপুন।');else if(e.error!=='aborted')note('স্যার, voice input সমস্যা: '+e.error)};r.onend=()=>{busy=false;B.classList.remove('listening');B.textContent='🎙'}};B.onclick=()=>{if(busy){try{r.stop()}catch(_){}return}try{build();r.start()}catch(e){note('স্যার, microphone চালু হয়নি। Browser microphone permission চেক করুন।')}}}
function playAIPop(){try{let C=window.AudioContext||window.webkitAudioContext;if(!C)return;let c=new C(),o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.setValueAtTime(430,c.currentTime);o.frequency.exponentialRampToValueAtTime(760,c.currentTime+.09);g.gain.setValueAtTime(.0001,c.currentTime);g.gain.exponentialRampToValueAtTime(.12,c.currentTime+.015);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+.14);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.15)}catch(_){}}
function homeAIHelloText(){let n=displayFirstName(),g=greetingNow();if(lang==='bn')return `হাই ${n} স্যার! ${g}`;return `Hi ${n} Sir! ${g}`}
function showAIHello(){q('#aiHello')?.remove();let h=document.createElement('div');h.id='aiHello';h.className='aiHelloBubble';h.innerHTML=`<strong>${esc(homeAIHelloText())}</strong><small>${lang==='bn'?'আমি আপনার Sales Assistant — AYON AI':'I am your Sales Assistant — AYON AI'}</small>`;document.body.appendChild(h);playAIPop();requestAnimationFrame(()=>h.classList.add('show'));setTimeout(()=>{h.classList.remove('show');setTimeout(()=>h.remove(),220)},3000)}
let aiWelcomeTimer=0,aiWelcomeStamp=0;
function scheduleAIWelcome(){clearTimeout(aiWelcomeTimer);let now=Date.now();if(now-aiWelcomeStamp<2500)return;aiWelcomeStamp=now;aiWelcomeTimer=setTimeout(()=>{if(currentPage==='home')showAIHello()},120)}
function askAIPopup(){let i=q('#aiPopupAsk'),s=i?.value.trim();if(!s)return;let c=q('#aiPopupChat'),res=aiAnswerRich(s),a=res.text;c.innerHTML+=`<div class="bubble me">${esc(s)}</div><div class="bubble bot">${esc(a)}${res.html||''}</div>`;i.value='';c.scrollTop=c.scrollHeight;aiSpeak(a)}
function aiKbNormalize(v){let z=String(v||'').toLowerCase().normalize('NFKC');const groups=[[/purchase\s*order|\bp\.?o\.?\b|পি\s*ও|পিও|অর্ডার|order/gi,' order '],[/buyer|customer|বায়ার|বায়ার|কাস্টমার|ক্রেতা/gi,' buyer '],[/sale|sales|সেলস|সেল/gi,' sales '],[/হচ্ছে\s*না|হচ্ছেনা|হয়\s*না|হয়\s*না|হয়না|হয়না|দিচ্ছে\s*না|দিচ্ছেনা|দিতে\s*চাচ্ছে\s*না|পাচ্ছি\s*না|পাচ্ছিনা|পাই\s*না|পাইনা|পারছি\s*না|পারছিনা|not\s+(?:giving|getting|happening)|no\s+/gi,' negative '],[/কোনোভাবেই|কোনভাবেই|কোনোভাবে|একদম|একেবারেই|anyway|at all/gi,' '],[/আজকে|আজ|today/gi,' today '],[/টার্গেট|target/gi,' target '],[/আউটলেট|outlet|shop|store/gi,' outlet '],[/ইনকাম|income|salary|বেতন/gi,' income '],[/জিরো\s*সেলস?|zero\s*sales?/gi,' zerosales '],[/রুট|route/gi,' route '],[/ডেলিভারি|delivery|delivered/gi,' delivery '],[/cpo|dpo/gi,' execution ']];for(const [re,to] of groups)z=z.replace(re,to);return z.replace(/[^a-z0-9\u0980-\u09ff]+/gi,' ').replace(/\s+/g,' ').trim()}
function aiKbTokens(v){const stop=new Set(['ভাই','স্যার','আমি','আমার','তো','যে','কি','কী','একটা','এই','ওই','হচ্ছে','হবে','করছে','করে','the','a','an','is','are','my','me','please']);return aiKbNormalize(v).split(' ').filter(x=>x.length>1&&!stop.has(x))}
function aiKbScore(a,b){let A=new Set(aiKbTokens(a)),B=new Set(aiKbTokens(b));if(!A.size||!B.size)return 0;let hit=0;A.forEach(x=>B.has(x)&&hit++);let coverage=hit/Math.min(A.size,B.size),jacc=hit/(A.size+B.size-hit);let na=aiKbNormalize(a),nb=aiKbNormalize(b);if(na===nb)return 1;if(na.includes(nb)||nb.includes(na))coverage=Math.max(coverage,.90);let anchors=['sales','order','buyer','negative','target','outlet','income','route','delivery','execution','zerosales'];let aa=anchors.filter(x=>A.has(x)),ab=anchors.filter(x=>B.has(x)),anchorHit=aa.filter(x=>ab.includes(x)).length;if(aa.length&&ab.length&&!anchorHit)return 0;let score=coverage*.78+jacc*.22;if(anchorHit>=2)score=Math.min(1,score+.12);return score}
function aiKbAnswer(s){let pairs=db.kb?.qaPairs||[],best=null,bestScore=0;for(let p of pairs){let variants=String(p.question||'').split(/[|;\/\n]+/).map(x=>x.trim()).filter(Boolean);for(let v of variants){let score=aiKbScore(s,v);if(score>bestScore){bestScore=score;best=p}}}window._ffhLastKbScore=bestScore;return best&&bestScore>=.34?best.answer:''}
function aiZeroSalesAnswer(){let id=currentSr(),ids=id?[id]:srIds(),rows=[];ids.forEach(sid=>zeroOutlets(sid).forEach(o=>rows.push({...o,sr:sid})));if(!rows.length)return lang==='bn'?'স্যার, এই scope-এ কোনো Zero Sales outlet নেই। সব assigned outlet covered।':'Sir, there are no zero-sales outlets in this scope. All assigned outlets are covered.';let preview=rows.slice(0,8).map(o=>`${o.name}${isMgr()&&!id?' — '+short(sr(o.sr)?.name||o.sr):''}`).join(', ');return lang==='bn'?`স্যার, এই scope-এ মোট ${rows.length}টি Zero Sales outlet আছে। ${preview}${rows.length>8?' সহ আরও '+(rows.length-8)+'টি':''}।`:`Sir, there are ${rows.length} zero-sales outlets in this scope. ${preview}${rows.length>8?' and '+(rows.length-8)+' more':''}.`}
function aiAnswerRich(s){let z=s.toLowerCase(),nz=aiKbNormalize(s);if(/zero\s*sales?|জিরো\s*সেলস?|শূন্য\s*সেল/.test(z)||nz.includes('zerosales'))return{text:aiZeroSalesAnswer(),html:''};let kb=aiKbAnswer(s);if(kb)return{text:kb,html:''};if(/তোমাকে.*কে.*তৈরি|তোমাকে.*কে.*বান|আপনাকে.*কে.*তৈরি|আপনাকে.*কে.*বান|কে.*তৈরি.*করেছে|কে.*বানিয়েছে|কে.*বানিয়েছে|creator|created you|who made you|who created you|made you/.test(z))return{text:aiAnswer(s),html:''};if(/proposal|প্রপোজাল|pdf|ফর্ম/.test(z)){let words=z.split(/\s+/).filter(x=>x.length>2),hit=(db.proposals||[]).find(p=>words.some(w=>String(p.name||'').toLowerCase().includes(w)));if(!hit&&(db.proposals||[]).length===1)hit=db.proposals[0];if(hit&&hit.file)return{text:`স্যার, ${hit.name} proposal form পেয়েছি। নিচের বাটন থেকে PDF ডাউনলোড করতে পারবেন।`,html:`<a class="aiPdfDownload" href="${hit.file}" download="${esc(hit.filename||hit.name+'.pdf')}">⬇ DOWNLOAD PDF</a>`};if((db.proposals||[]).length)return{text:lang==='bn'?'স্যার, Proposal Library-তে ফাইল আছে। নাম/চেইনটা একটু নির্দিষ্ট করে বলুন।':'Sir, files are available in Proposal Library. Please tell me the proposal/chain name.',html:''};}
if(/task|টাস্ক/.test(z)){let rows=(db.tasks||[]).filter(x=>isMgr()||x.to===user.id||x.from===user.id);let open=rows.filter(x=>!/done|complete/i.test(x.status||'')).length;return{text:lang==='bn'?`স্যার, আপনার scope-এ ${rows.length}টি task আছে; ${open}টি এখনো open।`:`Sir, ${rows.length} tasks are in your scope; ${open} are still open.`,html:''}}if(/catalog|catalogue|ক্যাটালগ|sku|product|প্রোডাক্ট/.test(z)){let words=z.split(/\s+/).filter(x=>x.length>2),hit=(catalogueProducts()||[]).filter(p=>words.some(w=>String(p).toLowerCase().includes(w))).slice(0,8);return{text:hit.length?(lang==='bn'?`স্যার, Catalogue-এ মিলেছে: ${hit.join(', ')}।`:`Sir, I found these in Catalogue: ${hit.join(', ')}.`):(lang==='bn'?'স্যার, Catalogue-এ এই নামে কোনো SKU পাইনি।':'Sir, I could not find a matching SKU in Catalogue.'),html:''}}if(/task|টাস্ক/.test(z)){let rows=(db.tasks||[]).filter(x=>isMgr()||x.to===user.id||x.from===user.id);let open=rows.filter(x=>!/done|complete/i.test(x.status||'')).length;return{text:lang==='bn'?`স্যার, আপনার scope-এ ${rows.length}টি task আছে; ${open}টি এখনো open।`:`Sir, ${rows.length} tasks are in your scope; ${open} are still open.`,html:''}}if(/catalog|catalogue|ক্যাটালগ|sku|product|প্রোডাক্ট/.test(z)){let words=z.split(/\s+/).filter(x=>x.length>2),hit=(catalogueProducts()||[]).filter(p=>words.some(w=>String(p).toLowerCase().includes(w))).slice(0,8);return{text:hit.length?(lang==='bn'?`স্যার, Catalogue-এ মিলেছে: ${hit.join(', ')}।`:`Sir, I found these in Catalogue: ${hit.join(', ')}.`):(lang==='bn'?'স্যার, Catalogue-এ এই নামে কোনো SKU পাইনি।':'Sir, I could not find a matching SKU in Catalogue.'),html:''}}return{text:aiAnswer(s),html:''}}

